// Example with custom object/key type
struct Data { int id; };
struct DataComp {
    bool operator()(const Data& a, const Data& b) const {
        return a.id < b.id;
    }
};
std::multiset<Data, DataComp> MS;
MS.emplace(Data{42});
// Elements in MS are also immutable const Data
